parameters.jsCode:
const input = $input.first().json;

const content = input?.choices?.[0]?.message?.content;

if (!content) {
  throw new Error(
    "لم يرجع Groq أي محتوى. الاستجابة الكاملة: " +
    JSON.stringify(input)
  );
}

let cleanedContent = String(content).trim();

// حذف التفكير في حال ظهر رغم تعطيله
cleanedContent = cleanedContent
  .replace(/<think\b[^>]*>[\s\S]*?<\/think>/gi, "")
  .replace(/```json/gi, "")
  .replace(/```/g, "")
  .trim();

let parsedData;

try {
  // المحاولة الأولى: الاستجابة كلها JSON
  parsedData = JSON.parse(cleanedContent);
} catch (firstError) {
  // المحاولة الثانية: استخراج كائن JSON من داخل النص
  const firstBrace = cleanedContent.indexOf("{");
  const lastBrace = cleanedContent.lastIndexOf("}");

  if (firstBrace === -1 || lastBrace === -1) {
    throw new Error(
      "لم يتم العثور على JSON في استجابة Groq:\n" +
      cleanedContent
    );
  }

  const jsonText = cleanedContent.slice(
    firstBrace,
    lastBrace + 1
  );

  try {
    parsedData = JSON.parse(jsonText);
  } catch (secondError) {
    throw new Error(
      "Groq أعاد JSON غير صالح:\n" +
      jsonText +
      "\n\nسبب الخطأ: " +
      secondError.message
    );
  }
}

// توحيد الحقول ومنع فقدان الصفر الأول في رقم الهاتف
return [
  {
    json: {
      crm_order_id: String(
        parsedData.crm_order_id ?? ""
      ).trim(),

      customer_name: String(
        parsedData.customer_name ?? ""
      ).trim(),

      contact_phone: String(
        parsedData.contact_phone ?? ""
      ).trim(),

      internet_service_no: String(
        parsedData.internet_service_no ?? ""
      ).trim()
    }
  }
];
